import React, { useEffect, useRef, useState } from 'react';

export default function BrideGroomSection() {
  const [visible, setVisible] = useState(false);
  const ref = useRef();

  useEffect(() => {
    const obs = new IntersectionObserver(([e]) => {
      if (e.isIntersecting) setVisible(true);
    }, { threshold: 0.2 });
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);

  return (
    <section ref={ref} style={{
      background: 'linear-gradient(180deg, #fce8f5 0%, #fdf0f8 100%)',
      padding: '20px 20px 80px',
      textAlign: 'center',
    }}>
      <style>{`
        @keyframes slideLeft {
          from { opacity: 0; transform: translateX(-50px); }
          to { opacity: 1; transform: translateX(0); }
        }
        @keyframes slideRight {
          from { opacity: 0; transform: translateX(50px); }
          to { opacity: 1; transform: translateX(0); }
        }
        @keyframes scaleIn {
          from { opacity: 0; transform: scale(0.8); }
          to { opacity: 1; transform: scale(1); }
        }
        .sl { opacity: 0; }
        .sr { opacity: 0; }
        .sc { opacity: 0; }
        .sl.vis { animation: slideLeft 0.8s ease 0.2s forwards; }
        .sr.vis { animation: slideRight 0.8s ease 0.4s forwards; }
        .sc.vis { animation: scaleIn 0.6s ease 0.1s forwards; }
        .couple-full-photo {
          width: 280px;
          height: 280px;
          border-radius: 50% 50% 50% 50% / 45% 45% 55% 55%;
          overflow: hidden;
          margin: 0 auto 40px;
          box-shadow: 0 10px 40px rgba(233,30,140,0.22);
          border: 4px solid rgba(233,30,140,0.18);
          position: relative;
        }
        .couple-full-photo img {
          width: 100%;
          height: 100%;
          object-fit: cover;
          object-position: 50% 20%;
          display: block;
        }
      `}</style>

      {/* Foto couple */}
      <div className={`sc${visible ? ' vis' : ''}`}>
        <div className="couple-full-photo">
          <img src="/foto-couple.jpg" alt="Eko & Armita" />
        </div>
      </div>

      {/* Nama mempelai */}
      <div style={{
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        gap: '20px',
        flexWrap: 'wrap',
        maxWidth: '900px',
        margin: '0 auto',
      }}>
        {/* Mempelai Pria */}
        <div className={`sl${visible ? ' vis' : ''}`} style={{ flex: 1, minWidth: '220px', textAlign: 'center' }}>
          <h2 style={{
            fontFamily: "'Dancing Script', cursive",
            fontSize: 'clamp(1.8rem, 5vw, 2.5rem)',
            color: '#333',
            marginBottom: '8px',
          }}>
            Eko Febriyanto
          </h2>
          <p style={{
            fontFamily: "'Poppins', sans-serif",
            fontSize: '0.9rem',
            color: '#666',
            marginBottom: '4px',
          }}>
            Putra dari: 
          </p>
          <p style={{
            fontFamily: "'Poppins', sans-serif",
            fontSize: '0.88rem',
            color: '#555',
            fontWeight: 500,
            lineHeight: 1.6,
          }}>
            Bp. Sholikin &amp; Ibu Siti Sumarsih
            Sruwen
          </p>
        </div>

        {/* Ampersand */}
        <div style={{
          fontFamily: "'Dancing Script', cursive",
          fontSize: '2.5rem',
          color: '#e91e8c',
          padding: '0 10px',
        }}>&amp;</div>

        {/* Mempelai Wanita */}
        <div className={`sr${visible ? ' vis' : ''}`} style={{ flex: 1, minWidth: '220px', textAlign: 'center' }}>
          <h2 style={{
            fontFamily: "'Dancing Script', cursive",
            fontSize: 'clamp(1.8rem, 5vw, 2.5rem)',
            color: '#333',
            marginBottom: '8px',
          }}>
            Armita Elza Saputri
          </h2>
          <p style={{
            fontFamily: "'Poppins', sans-serif",
            fontSize: '0.9rem',
            color: '#666',
            marginBottom: '4px',
          }}>
            Putri dari:
          </p>
          <p style={{
            fontFamily: "'Poppins', sans-serif",
            fontSize: '0.88rem',
            color: '#555',
            fontWeight: 500,
            lineHeight: 1.6,
          }}>
            Bp. Muhamad Fahrudin &amp; Ibu Sri Jumiyatun
          </p>
        </div>
      </div>
    </section>
  );
}
